135	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
136	    @Override
137	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
138	        return withOwner(ownerId, owner ->
139	            new ResponseEntity<>(toOwnerDtoWithDerivedFields(owner), HttpStatus.OK));
140	    }
141	
142	    /**
143	     * The request header carrying the caller's idempotency key. When a create is repeated with a key
144	     * already seen, the originally created owner is returned with 200 instead of a duplicate being
145	     * created (see {@link #addOwner(OwnerFieldsDto)} and {@link IdempotencyKeyStore}).
146	     */
147	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
148	
149	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
150	    @Override
151	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
152	        String idempotencyKey = currentIdempotencyKey();
153	        Optional<Owner> existing = idempotencyKeyStore.find(idempotencyKey)
154	            .map(this.clinicService::findOwnerById);
155	        if (existing.isPresent()) {
156	            return ownerResponse(existing.get(), HttpStatus.OK);
157	        }
158	        Owner owner = createOwner(ownerFieldsDto);
159	        idempotencyKeyStore.record(idempotencyKey, owner.getId());
160	        return ownerResponse(owner, HttpStatus.CREATED);
161	    }
162	
163	    /**
164	     * Reads the {@code Idempotency-Key} header from the current request, or {@code null} when no
165	     * request is bound or the header is absent. Held in one place so the create endpoint can decide,
166	     * from the key alone, whether a create is a first occurrence or a repeat to be served from the
167	     * originally created owner.
168	     *
169	     * @return the request's idempotency key, or {@code null} when none was supplied
170	     */
171	    private String currentIdempotencyKey() {
172	        if (RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attributes) {
173	            return attributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
174	        }
175	        return null;
176	    }
177	
178	    /**
179	     * Validates and normalizes the submitted owner fields, builds the owner, enforces the create-time
180	     * duplicate rules and persists it, returning the saved owner. This holds the whole "make and store
181	     * a new owner" flow in one place, separate from turning that owner into an HTTP response
182	     * ({@link #ownerResponse(Owner, HttpStatus)}), so the create endpoint reads as "create the owner,
183	     * then respond" and the persisted owner is available to callers that need it beyond the response.
184	     *
185	     * @param ownerFieldsDto the submitted owner fields, normalized in place as part of the create
186	     * @return the persisted owner, with its derived fields populated
187	     */
188	    private Owner createOwner(OwnerFieldsDto ownerFieldsDto) {
189	        normalizeAddress(ownerFieldsDto);
190	        rejectBlankOwnerFields(ownerFieldsDto);
191	        rejectDisposableEmailDomain(ownerFieldsDto.getEmail());
192	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
193	        rejectInvalidPostcode(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
194	        rejectCityAtCapacity(ownerFieldsDto.getCity());
195	        rejectFutureRegistrationDate(ownerFieldsDto.getRegistrationDate());
196	        LocalDate registrationDate = businessDay(effectiveRegistrationDate(ownerFieldsDto.getRegistrationDate()));
197	        rejectDailyRegistrationLimit(registrationDate);
198	        String normalizedTelephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
199	        ownerFieldsDto.setTelephone(normalizedTelephone);
200	        String normalizedEmail = emailNormalizer.normalize(ownerFieldsDto.getEmail());
201	        ownerFieldsDto.setEmail(normalizedEmail);
202	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
203	        owner.setRegistrationDate(registrationDate);
204	        owner.setCustomerCode(customerCode(owner));
205	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
206	        owner.setHouseholdId(householdId(owner));
207	        rejectDuplicateIdentity(owner);
208	        rejectHouseholdDuplicate(owner, sharesHousehold);
209	        owner.setPossibleDuplicateOf(sharesHousehold ? null : possibleDuplicateOf(owner));
210	        this.clinicService.saveOwner(owner);
211	        owner.setHouseholdSize(householdSize(owner));
212	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
213	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
214	            ownerMapper.membershipLevel(owner), ownerMapper.membershipNumber(owner));
215	        return owner;
216	    }
217	
218	    /**
219	     * Builds the response for an owner: its derived-field DTO (see
220	     * {@link #toOwnerDtoWithDerivedFields(Owner)}) as the body and a {@code Location} header pointing at
221	     * the owner's canonical URL, returned with the given {@code status}. Assembling the response in one
222	     * place keeps "what to return for an owner" separate from the create flow that produced it, so any
223	     * path that returns an owner does so identically (differing only in the status it carries).
224	     *
225	     * @param owner the persisted owner to represent
226	     * @param status the HTTP status to return
227	     * @return the owner response with its body, {@code Location} header and status
228	     */
229	    private ResponseEntity<OwnerDto> ownerResponse(Owner owner, HttpStatus status) {
230	        OwnerDto ownerDto = toOwnerDtoWithDerivedFields(owner);
231	        HttpHeaders headers = new HttpHeaders();
232	        headers.setLocation(UriComponentsBuilder.newInstance()
233	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
234	        return new ResponseEntity<>(ownerDto, headers, status);
235	    }
