239	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
240	        return withOwner(ownerId, currentOwner -> {
241	            currentOwner.setAddress(ownerFieldsDto.getAddress());
242	            currentOwner.setCity(ownerFieldsDto.getCity());
243	            currentOwner.setFirstName(ownerFieldsDto.getFirstName());
244	            currentOwner.setLastName(ownerFieldsDto.getLastName());
245	            currentOwner.setTelephone(ownerFieldsDto.getTelephone());
246	            currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
247	            this.clinicService.saveOwner(currentOwner);
248	            return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
249	        });
250	    }
