326	    /**
327	     * Loads the owner with the given id and, when it exists, produces the response through
328	     * {@code action}; when no such owner exists a {@code 404 Not Found} is returned instead. The
329	     * single-owner endpoints share this "find the owner or report 404" preamble, so the lookup and
330	     * the not-found response are written in exactly one place rather than copied into each method.
331	     *
332	     * @param ownerId the id of the owner to load
333	     * @param action builds the response for an existing owner
334	     * @param <T> the response body type
335	     * @return the result of {@code action} for an existing owner, otherwise a 404 response
336	     */
337	    private <T> ResponseEntity<T> withOwner(Integer ownerId, Function<Owner, ResponseEntity<T>> action) {
338	        Owner owner = this.clinicService.findOwnerById(ownerId);
339	        if (owner == null) {
340	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
341	        }
342	        return action.apply(owner);
343	    }
344	
345	    /**
346	     * Maps a persisted owner to its {@link OwnerDto} and populates the read-only fields that are
347	     * derived from server-side state rather than stored columns (the {@code bulkSignupWarning} flag
348	     * and the {@code identityKey}). Both the create endpoint and the single-owner read endpoint
349	     * return their owner through this method, so an owner is decorated identically on either path
350	     * and each derived field is computed in exactly one place.
351	     *
352	     * @param owner the persisted owner to represent
353	     * @return the owner DTO with its derived read-only fields populated
354	     */
355	    private OwnerDto toOwnerDtoWithDerivedFields(Owner owner) {
356	        owner.setHouseholdSize(householdSize(owner));
357	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
358	        ownerDto.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
359	        ownerDto.setIdentityKey(identityKey(owner));
360	        Integer possibleDuplicateOf = owner.getPossibleDuplicateOf();
361	        ownerDto.setPossibleDuplicate(possibleDuplicateOf != null);
362	        ownerDto.setPossibleDuplicateOf(possibleDuplicateOf);
363	        return ownerDto;
364	    }
365	
366	    /**
367	     * Canonicalizes the submitted address in place before it is validated, stored and returned, so
368	     * every later step - the required-field check, the persisted value and the response - sees the
369	     * single normalized form produced by {@link AddressNormalizer#normalize(String)} (see that method
370	     * for the trim/collapse/upper-case/abbreviation rules). Normalizing once here, at the head of the
371	     * create flow, keeps address canonicalization in exactly one place rather than spread across the
372	     * steps that read the address.
373	     *
374	     * <p>An address may be supplied either as the structured {@code addressLine1} (with an optional
375	     * {@code addressLine2}) or as the single flat {@code address}, the latter kept for backward
376	     * compatibility. Whichever address fields are supplied are normalized, and the structured fields
377	     * are preferred when present: the flat {@code address} returned is composed as the normalized
378	     * {@code addressLine1}, with a single space and the normalized {@code addressLine2} appended when an
379	     * {@code addressLine2} is present; only when no {@code addressLine1} is supplied does the flat
380	     * {@code address} retain its own normalized value.
381	     *
382	     * @param ownerFieldsDto the submitted owner fields, whose address fields are replaced with their normalized form
383	     */
384	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
385	        String addressLine1 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine1());
386	        String addressLine2 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
387	        String flatAddress = addressNormalizer.normalize(ownerFieldsDto.getAddress());
388	        ownerFieldsDto.setAddressLine1(addressLine1);
389	        ownerFieldsDto.setAddressLine2(addressLine2);
390	        if (addressLine1 != null && !addressLine1.isBlank()) {
391	            String composed = addressLine2 != null && !addressLine2.isBlank()
392	                ? addressLine1 + " " + addressLine2
393	                : addressLine1;
394	            ownerFieldsDto.setAddress(composed);
395	        } else {
396	            ownerFieldsDto.setAddress(flatAddress);
397	        }
398	    }
399	
400	    /**
401	     * Rejects an owner whose required text fields are blank (whitespace-only). Missing (null)
402	     * and empty fields are already rejected by Bean Validation on {@link OwnerFieldsDto}; this
403	     * closes the gap for {@code address} and {@code city}, whose values may be non-empty yet
404	     * blank (e.g. {@code "   "}). The offending field names are reported through an
405	     * {@link InvalidOwnerFieldsException}, which the {@code ExceptionControllerAdvice} renders
406	     * as a 400 response carrying an {@code errors} array of field names.
407	     *
408	     * @param ownerFieldsDto the submitted owner fields
409	     * @throws InvalidOwnerFieldsException if one or more required fields are blank
410	     */
411	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
412	        List<String> blankFields = new ArrayList<>();
413	        addIfBlank(blankFields, "firstName", ownerFieldsDto.getFirstName());
414	        addIfBlank(blankFields, "lastName", ownerFieldsDto.getLastName());
415	        addRequiredAddress(blankFields, ownerFieldsDto);
416	        addIfBlank(blankFields, "city", ownerFieldsDto.getCity());
417	        addIfBlank(blankFields, "telephone", ownerFieldsDto.getTelephone());
418	        if (!blankFields.isEmpty()) {
419	            throw new InvalidOwnerFieldsException(blankFields);
420	        }
421	    }
422	
423	    private void addIfBlank(List<String> blankFields, String field, String value) {
424	        if (value != null && value.isBlank()) {
425	            blankFields.add(field);
426	        }
427	    }
428	
429	    /**
430	     * Records the address requirement's offending field name(s) into {@code blankFields}. An owner
431	     * must supply an address in EITHER accepted form: the structured {@code addressLine1} or the flat
432	     * {@code address} (kept for backward compatibility). The requirement is satisfied when at least one
433	     * of those is present and non-blank; only when both are missing or blank is {@code address} reported
434	     * as the offending field. Holding the "an owner must have an address" rule in its own method - rather
435	     * than a bare entry in the field list - gives it one place to live as the accepted address forms grow.
436	     *
437	     * @param blankFields the accumulating list of blank required-field names
438	     * @param ownerFieldsDto the submitted owner fields
439	     */
440	    private void addRequiredAddress(List<String> blankFields, OwnerFieldsDto ownerFieldsDto) {
441	        if (isBlank(ownerFieldsDto.getAddressLine1()) && isBlank(ownerFieldsDto.getAddress())) {
442	            blankFields.add("address");
443	        }
444	    }
445	
446	    private boolean isBlank(String value) {
447	        return value == null || value.isBlank();
448	    }
449	
450	    /**
451	     * Rejects an owner whose {@code email} domain is on the disposable-domain blocklist
452	     * ({@code mailinator.com}, {@code tempmail.com}, {@code guerrillamail.com}). Email is validated
453	     * only when present, so an owner created without one is accepted unchanged; syntactic validity is
454	     * already enforced by Bean Validation's {@code @Email} constraint on {@link OwnerFieldsDto}, so
455	     * this only rejects an otherwise well-formed address that uses a throwaway provider (see
456	     * {@link DisposableEmailDomains#isDisposable(String)} for the case-insensitive domain match). A
457	     * blocklisted address is reported through a {@link DisposableEmailDomainException}, which the
458	     * {@code ExceptionControllerAdvice} renders as a 400 response naming the {@code email} field.
459	     *
460	     * @param email the supplied email, or {@code null} when omitted
461	     * @throws DisposableEmailDomainException if the email's domain is blocklisted
462	     */
463	    private void rejectDisposableEmailDomain(String email) {
464	        if (disposableEmailDomains.isDisposable(email)) {
465	            throw new DisposableEmailDomainException(email);
466	        }
467	    }
468	
469	    /**
470	     * Validates the owner's optional {@code postcode} against its {@code city} region. Postcode is
471	     * validated only when present, so an owner created without one is accepted unchanged. A supplied
472	     * postcode is already constrained to four digits by Bean Validation on {@link OwnerFieldsDto}; this
473	     * additionally rejects a well-formed postcode that is out of range for the city's region using the
474	     * shared {@link Region#acceptsPostcode(int) region-to-postcode} table ({@code NSW 2000-2099},
475	     * {@code VIC 3000-3099}, {@code QLD 4000-4099}). A city with no known region accepts any 4-digit
476	     * postcode. An out-of-range postcode is reported through an {@link InvalidOwnerPostcodeException},
477	     * which the {@code ExceptionControllerAdvice} renders as a 400 response.
478	     *
479	     * @param city the city of the owner being created
480	     * @param postcode the supplied postcode, or {@code null} when omitted
481	     * @throws InvalidOwnerPostcodeException if the postcode is out of range for the city's region
482	     */
483	    private void rejectInvalidPostcode(String city, String postcode) {
484	        if (postcode == null || postcode.isBlank()) {
485	            return;
486	        }
487	        Region.forCity(city).ifPresent(region -> {
488	            if (!region.acceptsPostcode(Integer.parseInt(postcode))) {
489	                throw new InvalidOwnerPostcodeException(postcode, city);
490	            }
491	        });
492	    }
493	
494	    /**
495	     * Number of leading hex characters of the identity hash retained as the {@code HASH8} segment of
496	     * the {@code customerCode}.
497	     */
498	    private static final int CUSTOMER_CODE_HASH_LENGTH = 8;
499	
500	    /**
501	     * Builds the {@code customerCode} assigned to a newly created owner, formatted
502	     * {@code '<REGION>-<HASH8>'}: {@code REGION} is the owner's canonical region code resolved from
503	     * its {@code postcode} (falling back to its {@code city}) through the shared
504	     * {@link Region#code(String, String)}, and {@code HASH8} is the first 8 upper-case hex characters
505	     * of the SHA-256 digest of the owner's normalized telephone followed by its last name
506	     * (e.g. {@code 'NSW-1A2B3C4D'}). When this base code collides with an existing owner's
507	     * {@code customerCode}, {@code '-<n>'} is appended with the smallest {@code n} of 2 or more that
508	     * makes the result unique (e.g. {@code 'NSW-1A2B3C4D-2'}), so distinct owners always receive
509	     * distinct customer codes.
510	     *
511	     * @param owner the owner being created, with its telephone already normalized
512	     * @return the formatted, de-duplicated customer code
513	     */
514	    private String customerCode(Owner owner) {
515	        String region = Region.code(owner.getPostcode(), owner.getCity());
516	        String hash8 = hashPrefix(owner.getTelephone() + owner.getLastName(), CUSTOMER_CODE_HASH_LENGTH);
517	        String base = region + "-" + hash8;
518	        return deduplicateCustomerCode(base);
519	    }
520	
521	    /**
522	     * Ensures the given base {@code customerCode} does not collide with an existing owner's
523	     * {@code customerCode}. When no existing owner carries the base code it is returned unchanged;
524	     * otherwise {@code '-<n>'} is appended with the smallest {@code n} of 2 or more that yields a code
525	     * held by no existing owner.
526	     *
527	     * @param base the computed base customer code, formatted {@code '<REGION>-<HASH8>'}
528	     * @return the base code, or a {@code '<base>-<n>'} variant that is unique among existing owners
529	     */
530	    private String deduplicateCustomerCode(String base) {
531	        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
532	            .map(Owner::getCustomerCode)
533	            .filter(java.util.Objects::nonNull)
534	            .collect(java.util.stream.Collectors.toSet());
535	        if (!existing.contains(base)) {
536	            return base;
537	        }
538	        int n = 2;
539	        while (existing.contains(base + "-" + n)) {
540	            n++;
541	        }
542	        return base + "-" + n;
543	    }
544	
545	    /**
546	     * Counts how many existing owners already share the given {@code firstName} and {@code lastName},
547	     * compared case-insensitively (using {@link java.util.Locale#ROOT}-independent
548	     * {@link String#equalsIgnoreCase(String)}). The count reflects the owners present before the
549	     * current create, so a name that is unique on create yields {@code 0}. The value is stored on the
550	     * new owner and surfaced as the read-only {@code namesakeCount} field.
551	     *
552	     * @param firstName the first name of the owner being created
553	     * @param lastName the last name of the owner being created
554	     * @return the number of existing owners with the same first and last name (case-insensitive)
555	     */
556	    private int namesakeCount(String firstName, String lastName) {
557	        return (int) countOwners(owner -> equalsIgnoreCase(owner.getFirstName(), firstName)
558	            && equalsIgnoreCase(owner.getLastName(), lastName));
559	    }
560	
561	    private boolean equalsIgnoreCase(String a, String b) {
562	        return a == null ? b == null : a.equalsIgnoreCase(b);
563	    }
564	
565	    /**
566	     * The maximum number of owners a single city may contain. Once a city already holds this many
567	     * owners, further owners in that city are rejected by {@link #rejectCityAtCapacity(String)}.
568	     */
569	    private static final long MAX_OWNERS_PER_CITY = 50L;
570	
571	    /**
572	     * Rejects a create request whose city already contains {@link #MAX_OWNERS_PER_CITY} or more
573	     * owners. Existing owners are matched to the requested city case-insensitively (using
574	     * {@link java.util.Locale#ROOT}-independent {@link String#equalsIgnoreCase(String)}), mirroring
575	     * the per-city counting used for the customer code. A city at capacity is reported through an
576	     * {@link OwnerCityAtCapacityException}, which the {@code ExceptionControllerAdvice} renders as a
577	     * 409 Conflict response.
578	     *
579	     * @param city the city of the owner being created
580	     * @throws OwnerCityAtCapacityException if the city already holds the maximum number of owners
581	     */
582	    private void rejectCityAtCapacity(String city) {
583	        if (ownersInCity(city) >= MAX_OWNERS_PER_CITY) {
584	            throw new OwnerCityAtCapacityException(city);
585	        }
586	    }
587	
588	    /**
589	     * Counts the existing owners whose {@code city} matches the given city, compared
590	     * case-insensitively (see {@link #equalsIgnoreCase(String, String)}). Used by the per-city
591	     * capacity check ({@link #rejectCityAtCapacity(String)}) to count a city's owners.
592	     *
593	     * @param city the city to count owners for
594	     * @return the number of existing owners in that city
595	     */
596	    private long ownersInCity(String city) {
597	        return countOwners(owner -> equalsIgnoreCase(owner.getCity(), city));
598	    }
599	
600	    /**
601	     * The maximum number of owners that may be registered on a single day. Once this many owners
602	     * already carry a given {@code registrationDate}, further owners for that date are rejected by
603	     * {@link #rejectDailyRegistrationLimit(LocalDate)}.
604	     */
605	    private static final long MAX_OWNERS_PER_DAY = 100L;
606	
607	    /**
608	     * Resolves the effective registration date for a create request: the value supplied in the
609	     * request when present, otherwise the server's current date. The result is the raw effective
610	     * date before the business-day adjustment applied by {@link #businessDay(LocalDate)}.
611	     *
612	     * @param suppliedDate the registration date from the request, or {@code null} when omitted
613	     * @return the supplied date, or today when none was supplied
614	     */
615	    private LocalDate effectiveRegistrationDate(LocalDate suppliedDate) {
616	        return suppliedDate != null ? suppliedDate : LocalDate.now();
617	    }
618	
619	    /**
620	     * Rejects a create request whose supplied {@code registrationDate} lies after the server's
621	     * current date. A registration date may be supplied to backdate a create - and is defaulted to
622	     * today when omitted - but it may never be in the future. The check is applied to the raw
623	     * supplied value before the business-day adjustment ({@link #businessDay(LocalDate)}), so a
624	     * future date is rejected regardless of how that adjustment would move it. A future date is
625	     * reported through a {@link FutureRegistrationDateException}, which the
626	     * {@code ExceptionControllerAdvice} renders as a 400 Bad Request response naming the
627	     * {@code registrationDate} field.
628	     *
629	     * @param suppliedDate the registration date from the request, or {@code null} when omitted
630	     * @throws FutureRegistrationDateException if the supplied date is later than the server date
631	     */
632	    private void rejectFutureRegistrationDate(LocalDate suppliedDate) {
633	        if (suppliedDate != null && suppliedDate.isAfter(LocalDate.now())) {
634	            throw new FutureRegistrationDateException(suppliedDate);
635	        }
636	    }
637	
638	    /**
639	     * The fixed list of public holidays that are not business days. A registration date that lands
640	     * on one of these is rolled forward by {@link #businessDay(LocalDate)} to the next non-holiday
641	     * business day, exactly as it is rolled forward off a weekend.
642	     */
643	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
644	        LocalDate.of(2026, 1, 1),
645	        LocalDate.of(2026, 1, 26),
646	        LocalDate.of(2026, 4, 25),
647	        LocalDate.of(2026, 12, 25),
648	        LocalDate.of(2026, 12, 28));
649	
650	    /**
651	     * Adjusts a date so it falls on a business day, rolling forward off weekends and public
652	     * holidays. A Saturday, Sunday or {@link #PUBLIC_HOLIDAYS listed public holiday} is rolled
653	     * forward one day at a time until the first non-holiday weekday is reached; any other weekday is
654	     * returned unchanged. Applied to the effective registration date so that a weekend or holiday
655	     * value - whether supplied in the request or defaulted to the server date - is stored as the
656	     * next business day, and every value derived from the registration date (such as the membership
657	     * number's year segment and the daily create-limit bucket) uses the adjusted business day.
658	     *
659	     * @param date the effective registration date
660	     * @return the same date when it is a non-holiday weekday, otherwise the next business day
661	     */
662	    private LocalDate businessDay(LocalDate date) {
663	        while (isNonBusinessDay(date)) {
664	            date = date.plusDays(1);
665	        }
666	        return date;
667	    }
668	
669	    /**
670	     * Whether the given date is a weekend day or a listed public holiday, and so not a business day.
671	     *
672	     * @param date the date to test
673	     * @return {@code true} for a Saturday, Sunday or {@link #PUBLIC_HOLIDAYS listed public holiday}
674	     */
675	    private boolean isNonBusinessDay(LocalDate date) {
676	        DayOfWeek dayOfWeek = date.getDayOfWeek();
677	        return dayOfWeek == DayOfWeek.SATURDAY
678	            || dayOfWeek == DayOfWeek.SUNDAY
679	            || PUBLIC_HOLIDAYS.contains(date);
680	    }
681	
682	    /**
683	     * Rejects a create request once {@link #MAX_OWNERS_PER_DAY} or more owners have already been
684	     * created on the given day, counted by {@code registrationDate}. A day at capacity is reported
685	     * through a {@link DailyOwnerRegistrationLimitException}, which the {@code ExceptionControllerAdvice}
686	     * renders as a 429 Too Many Requests response.
687	     *
688	     * @param date the registration date of the owner being created (today)
689	     * @throws DailyOwnerRegistrationLimitException if the day already holds the maximum number of owners
690	     */
691	    private void rejectDailyRegistrationLimit(LocalDate date) {
692	        if (ownersRegisteredOn(date) >= MAX_OWNERS_PER_DAY) {
693	            throw new DailyOwnerRegistrationLimitException(date);
694	        }
695	    }
696	
697	    /**
698	     * Counts the existing owners whose {@code registrationDate} equals the given day. Shared by the
699	     * hard daily create limit ({@link #rejectDailyRegistrationLimit(LocalDate)}) and the soft
700	     * {@code bulkSignupWarning} flag ({@link #bulkSignupWarning(LocalDate)}) so both accumulate a
701	     * day's owners identically.
702	     *
703	     * @param date the registration date to count owners for
704	     * @return the number of existing owners registered on that day
705	     */
706	    private long ownersRegisteredOn(LocalDate date) {
707	        return countOwners(owner -> date.equals(owner.getRegistrationDate()));
708	    }
709	
710	    /**
711	     * The soft daily create threshold above which the read-only {@code bulkSignupWarning} flag is
712	     * raised. Once more than this many owners share a {@code registrationDate}, that day is flagged
713	     * as unusually high volume - a warning well below the hard {@link #MAX_OWNERS_PER_DAY} cap.
714	     */
715	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80L;
716	
717	    /**
718	     * Derives the read-only {@code bulkSignupWarning} flag for an owner: {@code true} when more than
719	     * {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have been created (counted by
720	     * {@code registrationDate}) on the given day, otherwise {@code false}. Uses the same per-day
721	     * accumulation as {@link #rejectDailyRegistrationLimit(LocalDate)}. A {@code null} date (an owner
722	     * without a registration date, such as seed data) is never flagged.
723	     *
724	     * @param date the owner's registration date (the day it was created), or {@code null}
725	     * @return {@code true} if the day already holds more than the warning threshold of owners
726	     */
727	    private boolean bulkSignupWarning(LocalDate date) {
728	        if (date == null) {
729	            return false;
730	        }
731	        return ownersRegisteredOn(date) > BULK_SIGNUP_WARNING_THRESHOLD;
732	    }
733	
734	    /**
735	     * Rejects a create request whose derived {@code identityKey} exactly equals an existing owner's.
736	     * The identity key consolidates the former separate telephone, email and household duplicate
737	     * checks into a single value: {@code normalizedTelephone + '|' + (email or empty) + '|' +
738	     * (householdId or empty)} (see {@link #identityKey(Owner)}). Because the telephone is part of the
739	     * key, two members of the same household (same {@code householdId}) with different telephones have
740	     * different identity keys and are both allowed; only an exact full-key match is a duplicate. A
741	     * collision is reported through a {@link DuplicateOwnerIdentityException}, which the
742	     * {@code ExceptionControllerAdvice} renders as a 409 Conflict response.
743	     *
744	     * @param owner the fully-populated owner being created (telephone, email and household id set)
745	     * @throws DuplicateOwnerIdentityException if an existing owner has the same identity key
746	     */
747	    private void rejectDuplicateIdentity(Owner owner) {
748	        String key = identityKey(owner);
749	        boolean duplicate = existingOwnerMatches(this::identityKey, key);
750	        if (duplicate) {
751	            throw new DuplicateOwnerIdentityException(key);
752	        }
753	    }
754	
755	    /**
756	     * Rejects a create request that would join an existing household unless it declares the shared
757	     * household with {@code sharesHousehold}. The household is keyed on {@code (lastName, postcode)}
758	     * through the deterministic {@link #householdId(Owner)}, so any existing owner with the same last
759	     * name and postcode is a member of the same household. A second such owner is a household
760	     * duplicate and is rejected with a 409 (via {@link DuplicateOwnerIdentityException}); setting
761	     * {@code sharesHousehold} bypasses this block, so the owner is created as a declared household
762	     * member instead. Owners without a {@code householdId} (e.g. no postcode) have no household to
763	     * collide with and are always allowed.
764	     *
765	     * @param owner the fully-populated owner being created (household id set)
766	     * @param sharesHousehold whether the request declared it shares an existing household
767	     * @throws DuplicateOwnerIdentityException if the household already exists and was not declared
768	     */
769	    private void rejectHouseholdDuplicate(Owner owner, boolean sharesHousehold) {
770	        if (sharesHousehold) {
771	            return;
772	        }
773	        String household = owner.getHouseholdId();
774	        if (household == null) {
775	            return;
776	        }
777	        if (existingOwnerMatches(this::householdId, household)) {
778	            throw new DuplicateOwnerIdentityException(identityKey(owner));
779	        }
780	    }
781	
782	    /**
783	     * Computes the soft-match {@code possibleDuplicateOf} for a newly created owner: the id of the
784	     * first existing owner that shares this owner's {@code lastName} (compared case-insensitively) and
785	     * {@code postcode} while carrying a <em>different</em> telephone (compared by canonical E.164 form,
786	     * see {@link TelephoneNormalizer#canonicalize(String)}), or {@code null} when no such owner exists.
787	     * The check runs only after the exact-identity duplicate check ({@link #rejectDuplicateIdentity(Owner)})
788	     * has passed, so a shared last-name-and-postcode with the same telephone has already been rejected as
789	     * a hard duplicate and can never surface here. A blank {@code postcode} never matches, since two
790	     * owners without a postcode do not share one. The captured id is stored on the new owner and surfaced
791	     * as the read-only {@code possibleDuplicate} / {@code possibleDuplicateOf} fields.
792	     *
793	     * @param owner the fully-populated owner being created (telephone normalized)
794	     * @return the id of the first soft-matching existing owner, or {@code null} when none matches
795	     */
796	    private Integer possibleDuplicateOf(Owner owner) {
797	        if (owner.getPostcode() == null || owner.getPostcode().isBlank()) {
798	            return null;
799	        }
800	        String telephone = telephoneNormalizer.canonicalize(owner.getTelephone());
801	        return this.clinicService.findAllOwners().stream()
802	            .filter(existing -> equalsIgnoreCase(existing.getLastName(), owner.getLastName())
803	                && owner.getPostcode().equals(existing.getPostcode())
804	                && !java.util.Objects.equals(telephone, telephoneNormalizer.canonicalize(existing.getTelephone())))
805	            .map(Owner::getId)
806	            .filter(java.util.Objects::nonNull)
807	            .findFirst()
808	            .orElse(null);
809	    }
810	
811	    /**
812	     * Reduces an owner to its derived {@code identityKey}, formatted
813	     * {@code '<normalizedTelephone>|<email>|<householdId>'}: the owner's telephone reduced to its
814	     * canonical E.164 form (see {@link TelephoneNormalizer#canonicalize(String)}), the owner's
815	     * normalized (lower-cased) email or the empty string when absent (see
816	     * {@link EmailNormalizer#normalize(String)}), and the owner's {@code householdId} or the empty
817	     * string when absent, joined by {@code '|'}. Two owners are duplicates exactly when their whole
818	     * identity keys are equal. The key never contains {@code null} segments, so the create endpoint's
819	     * single duplicate check compares this one value across owners.
820	     *
821	     * @param owner the owner to derive the identity key for
822	     * @return the owner's identity key
823	     */
824	    private String identityKey(Owner owner) {
825	        String telephone = telephoneNormalizer.canonicalize(owner.getTelephone());
826	        String normalizedEmail = emailNormalizer.normalize(owner.getEmail());
827	        String email = normalizedEmail == null ? "" : normalizedEmail;
828	        String household = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
829	        return telephone + "|" + email + "|" + household;
830	    }
831	
832	    /**
833	     * Finds the first existing owner that already carries the given comparison {@code key}, derived
834	     * from each owner by {@code keyExtractor}. Owners for which the extractor yields {@code null} are
835	     * ignored (a {@code null} key never equals the sought key). The create endpoint's duplicate
836	     * checks reduce both an existing owner and the owner being created to the same canonical key;
837	     * this returns the matched existing owner itself, so a caller can either reject the collision or
838	     * record which owner was matched. Owners flagged deleted (soft-deleted) are excluded, so a
839	     * collision with only a deleted owner is not reported and the create is allowed.
840	     *
841	     * @param keyExtractor derives an owner's canonical comparison key (may return {@code null})
842	     * @param key the canonical key of the owner being created
843	     * @return the first existing owner sharing the key, or empty when none does
844	     */
845	    private Optional<Owner> findExistingOwner(Function<Owner, String> keyExtractor, String key) {
846	        return this.clinicService.findAllOwners().stream()
847	            .filter(owner -> !owner.isDeleted())
848	            .filter(owner -> key.equals(keyExtractor.apply(owner)))
849	            .findFirst();
850	    }
851	
852	    /**
853	     * Reports whether any existing owner already carries the given comparison {@code key}, derived
854	     * from each owner by {@code keyExtractor} (see {@link #findExistingOwner(Function, String)}).
855	     * The create endpoint's duplicate checks use this to reduce both an existing owner and the owner
856	     * being created to the same canonical key and reject a match.
857	     *
858	     * @param keyExtractor derives an owner's canonical comparison key (may return {@code null})
859	     * @param key the canonical key of the owner being created
860	     * @return {@code true} if some existing owner shares the key
861	     */
862	    private boolean existingOwnerMatches(Function<Owner, String> keyExtractor, String key) {
863	        return findExistingOwner(keyExtractor, key).isPresent();
864	    }
865	
866	    /**
867	     * Counts the existing owners that satisfy the given {@code predicate}. The create endpoint's
868	     * count-based rules - the per-city capacity, the per-day create limit and the derived
869	     * {@code namesakeCount} - all accumulate owners over {@link ClinicService#findAllOwners()} and
870	     * differ only in the predicate they count by, so the scan-and-count is written in exactly one
871	     * place and each rule supplies just its own predicate.
872	     *
873	     * @param predicate the condition an owner must satisfy to be counted
874	     * @return the number of existing owners that satisfy the predicate
875	     */
876	    private long countOwners(Predicate<Owner> predicate) {
877	        return this.clinicService.findAllOwners().stream()
878	            .filter(predicate)
879	            .count();
880	    }
881	
882	    /**
883	     * Delimiter joining the canonical {@code lastName} and the {@code postcode} when deriving the
884	     * shared {@code householdId}.
885	     */
886	    private static final String HOUSEHOLD_KEY_DELIMITER = "|";
887	
888	    /**
889	     * Reduces the household {@code lastName} to a canonical form for case-insensitive,
890	     * whitespace-insensitive comparison: leading and trailing whitespace is trimmed, every run of
891	     * internal whitespace is collapsed to a single space, and the result is lower-cased using
892	     * {@link java.util.Locale#ROOT} so comparison is locale-independent.
893	     *
894	     * @param value the raw field value, or {@code null}
895	     * @return the canonical value, or {@code null} when {@code value} is {@code null}
896	     */
897	    private String canonicalizeHousehold(String value) {
898	        return value == null ? null : value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
899	    }
900	
901	    /**
902	     * Derives the deterministic, shared {@code householdId} for an owner from its {@code lastName}
903	     * and {@code postcode}. The identifier is the first 12 upper-case hex characters of the SHA-256
904	     * hash of {@code normalizedLastName + '|' + postcode} (see {@link #canonicalizeHousehold(String)}
905	     * for the last-name normalization), so every owner with the same last name and postcode -
906	     * regardless of casing or spacing - is automatically assigned the identical value. Owners without
907	     * a postcode have no household basis and are given no household id ({@code null}).
908	     *
909	     * @param owner the owner being created
910	     * @return the shared household identifier, or {@code null} when the owner has no postcode
911	     */
912	    /**
913	     * Counts the owners in the given owner's household: the existing owners that share its
914	     * {@code householdId} (see {@link #householdId(Owner)}), which - because the owner being counted is
915	     * itself persisted before it is decorated - includes the owner. An owner with no {@code householdId}
916	     * (e.g. no postcode) has no shared household and counts as a household of one. The value feeds the
917	     * household factor of the owner's membership points.
918	     *
919	     * @param owner the owner whose household size is being derived
920	     * @return the number of owners in the owner's household (at least {@code 1})
921	     */
922	    private int householdSize(Owner owner) {
923	        String household = owner.getHouseholdId();
924	        if (household == null) {
925	            return 1;
926	        }
927	        return (int) countOwners(existing -> household.equals(existing.getHouseholdId()));
928	    }
929	
930	    private String householdId(Owner owner) {
931	        String postcode = owner.getPostcode();
932	        if (postcode == null || postcode.isBlank()) {
933	            return null;
934	        }
935	        String key = canonicalizeHousehold(owner.getLastName()) + HOUSEHOLD_KEY_DELIMITER + postcode;
936	        return hashPrefix(key, HOUSEHOLD_ID_LENGTH);
937	    }
938	
939	    /**
940	     * Number of leading hex characters of the household hash retained as the shared
941	     * {@code householdId}.
942	     */
943	    private static final int HOUSEHOLD_ID_LENGTH = 12;
944	
945	    /**
946	     * Computes the leading {@code length} upper-case hex characters of the SHA-256 digest of the
947	     * UTF-8 bytes of {@code input}. This is the shared hashing primitive behind the derived
948	     * identifiers that fingerprint owner fields - such as the household-scoped {@code householdId} -
949	     * so every such identifier is produced by the same algorithm and differs only in the value it
950	     * hashes and the number of hex characters it keeps.
951	     *
952	     * @param input the value to hash
953	     * @param length the number of leading hex characters to keep
954	     * @return the leading {@code length} upper-case hex characters of the SHA-256 digest
955	     */
956	    private String hashPrefix(String input, int length) {
957	        try {
958	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
959	                .digest(input.getBytes(java.nio.charset.StandardCharsets.UTF_8));
960	            StringBuilder sb = new StringBuilder(digest.length * 2);
961	            for (byte b : digest) {
962	                sb.append(String.format("%02X", b));
963	            }
964	            return sb.substring(0, length);
965	        } catch (java.security.NoSuchAlgorithmException e) {
966	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
967	        }
968	    }
969	}
