72	     * {@code EMAIL} when an email is present, otherwise {@code PHONE}.
73	     *
74	     * @param owner the owner being mapped
75	     * @return the derived contact preference
76	     */
77	    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
78	        return hasEmail(owner) ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
79	    }
80	
81	    /**
82	     * Reports whether the owner has a usable {@code email}: present and not blank (whitespace-only).
83	     * The presence of an email drives several derived fields (such as the {@code contactPreference}
84	     * and the {@code membershipLevel}), so the "has an email" test is written in exactly one place
85	     * rather than repeated at each use.
86	     *
87	     * @param owner the owner being mapped
88	     * @return {@code true} when the owner has a non-blank email
89	     */
90	    default boolean hasEmail(Owner owner) {
91	        return owner.getEmail() != null && !owner.getEmail().isBlank();
92	    }
93	
94	    /**
95	     * Derives the owner's {@code ageBand} from its {@code birthDate}, measured against the owner's
96	     * {@code registrationDate}: {@code MINOR} when under 18, {@code ADULT} for 18 to 64, and
97	     * {@code SENIOR} for 65 and over. Returns {@code null} when no birth date is present, in which
98	     * case the field is absent from the response. The age in whole years is the number of complete
99	     * years between the birth date and the registration date (see {@link java.time.Period}); when the
100	     * registration date is somehow absent the current date is used as the reference.
101	     *
102	     * @param owner the owner being mapped
103	     * @return the derived age band, or {@code null} when no birth date is present
104	     */
105	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
106	        java.time.LocalDate birthDate = owner.getBirthDate();
107	        if (birthDate == null) {
108	            return null;
109	        }
110	        java.time.LocalDate reference = owner.getRegistrationDate() != null
111	            ? owner.getRegistrationDate() : java.time.LocalDate.now();
112	        int age = java.time.Period.between(birthDate, reference).getYears();
113	        if (age < 18) {
114	            return OwnerDto.AgeBandEnum.MINOR;
115	        }
116	        if (age < 65) {
117	            return OwnerDto.AgeBandEnum.ADULT;
118	        }
119	        return OwnerDto.AgeBandEnum.SENIOR;
120	    }
121	
122	    /**
123	     * Derives the owner's {@code locality} as the {@code REGION} segment of its {@code customerCode}
124	     * (the part before the {@code '-'}), which is the owner's canonical region code baked into the
125	     * region-and-hash identity {@code '<REGION>-<HASH8>'}. When no customer code is present (e.g. seed
126	     * data) it falls back to resolving the region directly from the owner's {@code postcode} and
127	     * {@code city} through the shared {@link Region#code(String, String)}. Reading the region from the
128	     * identity keeps the locality consistent with the code an owner is issued.
129	     *
